const oldChange=handlerChange;handlerChange=e=>{const t=e.target;if(changeKeys[t.id]){ui[changeKeys[t.id]]=t.value;ui.catalogPage=ui.orderPage=1;render();return;}if(t.name?.match(/^day\d$/)){const f=t.form,i=t.name.slice(3);for(const k of ['start','end','start2','end2'])f.elements[k+i].disabled=!t.checked;t.closest('.v2-day').querySelector('small').textContent=t.checked?'Atiende':'No atiende';updateSchedule(f);return;}if(t.name?.match(/^(start|end)2?\d$/)){updateSchedule(t.form);return;}if(t.dataset.photo){const f=t.form,file=t.files[0],name=t.dataset.photo;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)return toast('Imagen PNG/JPG/WebP de hasta 2 MB','bad');const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),factor=Math.min(1,640/Math.max(img.width,img.height));c.width=Math.round(img.width*factor);c.height=Math.round(img.height*factor);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const data=c.toDataURL('image/webp',.78);f.elements[name].value=data;const preview=f.querySelector(`[data-preview="${name}"]`);preview.src=data;preview.hidden=false;};img.src=reader.result;};reader.readAsDataURL(file);return;}if(t.id==='product-mode'){const el=document.getElementById('immediate-stock');if(el)el.hidden=t.value==='preorder';}if(t.id==='role-switcher'){ui.registrationOwner=null;ui.verifyExpected=null;ui.predProduct='Todos';ui.predictionCategory='Todas';}oldChange(e);};
